function demo_robot()

% 修改为你们自己的参赛队号。
baseUrl = 'http://127.0.0.1:2026';
robotId = '<参赛队号>';
options = weboptions('MediaType', 'application/json', 'Timeout', 5);

enterRequest = baseRequest(robotId, 'enter-1');
enterResponse = post(baseUrl, '/enter', enterRequest, options);
if enterResponse.accepted ~= true
    fprintf('进入失败\n');
    return;
end

remainingTime = enterResponse.remaining_real_duration_s;
fprintf('本局可用现实时间：%d秒\n', remainingTime);

% 与第10节计时示例完全相同的四个动作。
actions = {
    '/measure', actionRequest(robotId, 'measure-1', 300, 400, 1);
    '/measure', actionRequest(robotId, 'measure-2', 300, 400, 2);
    '/clear', actionRequest(robotId, 'clear-1', 300, 0, 3);
    '/measure', actionRequest(robotId, 'measure-3', 300, 0, 2)
};

for i = 1:size(actions, 1)
    path = actions{i, 1};
    payload = actions{i, 2};
    % 如果因网络故障重试本动作，必须复用这个payload及其中的request_id。
    response = post(baseUrl, path, payload, options);
    if response.accepted ~= true
        fprintf('请求未执行\n');
        return;
    end

    if strcmp(path, '/measure')
        if strcmp(response.measure_result, 'direction')
            fprintf('示向度：%.2f度\n', response.svd_deg);
        elseif strcmp(response.measure_result, 'near')
            fprintf('距离过近，没有示向度\n');
        else
            fprintf('未测得信号\n');
        end
    else
        if strcmp(response.clear_result, 'success')
            fprintf('清除成功\n');
        else
            fprintf('清除位置附近没有目标\n');
        end
    end
end

exitRequest = baseRequest(robotId, 'exit-1');
exitResponse = post(baseUrl, '/exit', exitRequest, options);
if exitResponse.accepted == true
    fprintf('退出原因：%s\n', exitResponse.exit_reason);
end
end

function request = baseRequest(robotId, requestId)
request = struct( ...
    'arena_id', 'default', ...
    'robot_id', robotId, ...
    'request_id', requestId);
end

function request = actionRequest(robotId, requestId, x, y, channel)
request = baseRequest(robotId, requestId);
request.position = struct('x', x, 'y', y);
request.channel = channel;
end

function response = post(baseUrl, path, payload, options)
response = webwrite([baseUrl path], payload, options);
fprintf('%s  %s\n', path, jsonencode(response));
end

12. 编程注意事项
先在模拟器中在线登录，启动测试，等待界面显示机器狗接口已经就绪。
使用当前登录参赛队号作为 robot_id。
每个新动作使用新的 request_id；只在重试完全相同动作时复用原ID和原请求内容。
逐次等待响应，不得并发发送不同动作；正常串行合法动作没有速率上限。
同时检查HTTP状态和 accepted。accepted=false 时动作没有生效，virtual_time_s=0 不是当前虚拟时刻。
使用 /enter 返回的 remaining_real_duration_s 控制现实运行时间，不要固定假定有1200秒。
每次检测增加的5秒是虚拟耗时，现实中不需要等待5秒。
只有 measure_result="direction" 时才读取 svd_deg，并且不是精确的真实方位，有误差。
/clear 不切换测向机频道；只有成功的 /measure 可能会更新当前频道。
no_signal 不等于附近一定没有干扰源；也可能是超出接收距离或不在定向覆盖范围内。
测试超时、中止或其他原因结束测试后接口会关闭；不要尝试调用 /exit 查询原因。
程序判断JSON取值时使用 direction、near、no_signal、success、no_target_in_range 和 user_exit 等实际字符串，不依赖界面中文说明。
机器狗程序应该自行记录测试过程中的指令序列、响应信息等内容，模拟器没有这一功能。
倒计时未结束、测试已经结束或接口未开放时，连接可能直接失败，没有JSON体。
加密日志文件上传上限为2MB，与机器狗接口协议无关；机器狗程序应避免异常高频循环。
指令 | 含义 | 是否推进虚拟时钟
POST /enter | 进入目标区域，开始本次运行。 | 否
POST /measure | 到指定位置，对指定频道检测。 | 是
POST /clear | 到指定位置，尝试清除指定频道的干扰源。 | 是
POST /exit | 退出目标区域，结束本次运行。 | 否
字段 | 类型 | 含义
accepted | boolean | 模拟器是否接受本次请求。
real_timestamp_ms | number | 模拟器响应时的现实世界时间戳，单位为毫秒。
virtual_time_s | number | 虚拟时钟，单位为秒。
HTTP状态 | 含义
200，accepted=true | 动作已执行。
200，accepted=false | JSON结构合法，但当前测试状态拒绝动作；或存在未知字段；或 arena_id、robot_id 不匹配。
400 | JSON语法、重复键、缺失字段、字段类型、标识符格式、频道或坐标范围错误。
404 | 路径未知或路径不精确。
405 | 已知路径使用了非POST方法。
409 | 同一 request_id 对应了不同动作，或并发发送了不同动作。
413 | 请求体超过65536字节。
415 | Content-Type 或 Content-Encoding 不受支持。
429 | 连接/无效流量保护触发，或本局幂等记录达到上限。
500 | 模拟器内部错误。
字段 | 类型 | 必填 | 取值说明
arena_id | string | 是 | 必须是 "default"。
robot_id | string | 是 | 机器狗标识，非空字符串，参赛队号。
request_id | string | 是 | 请求标识，非空字符串。
字段 | 类型 | 取值说明
accepted | boolean | true。
real_timestamp_ms | number | 现实世界时间戳，单位为毫秒。
virtual_time_s | number | 进入后的虚拟时刻；/enter 不推进虚拟时钟。
max_virtual_duration_s | number | 模拟器配置的虚拟世界限时，默认 360000。
max_real_duration_s | number | 模拟器配置的现实世界限时，默认 1200。
remaining_real_duration_s | number | 本次测试从 /enter 成功起实际还能使用的完整现实时间秒数，整数范围 。
字段 | 类型 | 必填 | 取值说明
